import pathlib,json,subprocess,hashlib,time,sys
R=pathlib.Path(__file__).resolve().parents[2];A=R/'artifacts/photo-engine';O=A/'raw-runs';O.mkdir(exist_ok=True);manifest=json.loads((R/'docs/evidence/wpf-failures-20261016/START.json').read_text(encoding='utf-8-sig'))
inputs=json.loads((R/'docs/evidence/controlled-icc-20261015/01_FROZEN_CONTRACTS.json').read_text())['inputs'];rows=[]
for f in inputs:
 p=pathlib.Path(f['path']);h=hashlib.sha256(p.read_bytes()).hexdigest();assert h==f['sha256'];out=O/(f['file']+'.linear-prophoto.tif');cmd=[str(A/'raw_candidate.exe'),str(p),str(out),'4','0'];start=time.perf_counter();r=subprocess.run(cmd,capture_output=True,text=True,timeout=180);(O/(f['file']+'.stdout')).write_text(r.stdout);(O/(f['file']+'.stderr')).write_text(r.stderr);rows.append(dict(file=f['file'],sourceSha256=h,command=cmd,code=r.returncode,milliseconds=(time.perf_counter()-start)*1000,stdout=r.stdout,stderr=r.stderr,sourceUnchanged=hashlib.sha256(p.read_bytes()).hexdigest()==h,outputSha256=hashlib.sha256(out.read_bytes()).hexdigest() if out.exists() else None))
sony=next(f for f in inputs if f['file'].endswith('.ARW'));cmd=[str(A/'raw_candidate.exe'),sony['path'],str(O/'cancel-should-not-exist.tif'),'4','100'];r=subprocess.run(cmd,capture_output=True,text=True,timeout=60);rows.append(dict(file=sony['file'],operation='callbackCancel100ms',command=cmd,code=r.returncode,stdout=r.stdout,stderr=r.stderr,outputExists=(O/'cancel-should-not-exist.tif').exists()))
for n,b in [('truncated.ARW',b'II*\0'+bytes(8)),('unknown.CR3',b'not-a-raw-file')]:
 p=O/n;p.write_bytes(b);r=subprocess.run([str(A/'raw_candidate.exe'),str(p),str(O/(n+'.tif')),'4','0'],capture_output=True,text=True,timeout=15);rows.append(dict(file=n,operation='boundaryInvalid',sha256=hashlib.sha256(b).hexdigest(),code=r.returncode,stdout=r.stdout,stderr=r.stderr,outputExists=(O/(n+'.tif')).exists()))
(A/'raw-results.json').write_text(json.dumps(rows,indent=2));print(json.dumps([dict(file=r['file'],operation=r.get('operation','fullLinearDecode'),code=r['code'],output=r.get('outputSha256')) for r in rows],indent=2))
